messages.content:
Game edukasi pemilahan sampah dengan tema Cartoon dan tempo Normal siap dibangun; item kantong plastik dan styrofoam sengaja dipakai untuk meluruskan miskonsepsi "semua plastik bisa didaur ulang".

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "pilah-sampah-run", title: "Pilah Sampah Run", seed: "pilah-sampah-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Lingkungan Hidup",
    concept: "Pemilahan sampah organik dan anorganik",
    objectives: ["Mengelompokkan sampah berdasarkan sifatnya (organik vs anorganik)"],
    misconceptions: ["Semua sampah plastik pasti bisa didaur ulang"],
    mode: "category",
    categories: [
      { id: "organik",   label: "Organik",   color: "#3FA34D" },
      { id: "anorganik", label: "Anorganik", color: "#2F80ED" }
    ],
    items: [
      { id: "kulit-pisang", label: "Kulit pisang",    category: "organik",   explain: "Sisa makhluk hidup; terurai alami dan bisa dijadikan kompos." },
      { id: "daun-kering",  label: "Daun kering",     category: "organik",   explain: "Bahan alami dari tumbuhan yang membusuk menjadi kompos." },
      { id: "sisa-nasi",    label: "Sisa nasi",       category: "organik",   explain: "Sisa makanan yang cepat membusuk dan bisa dikomposkan." },
      { id: "botol",        label: "Botol plastik",   category: "anorganik", explain: "Sulit terurai, tetapi jenis plastik ini bisa didaur ulang." },
      { id: "kaleng",       label: "Kaleng minuman",  category: "anorganik", explain: "Logam buatan; bisa didaur ulang berulang kali." },
      { id: "kantong",      label: "Kantong plastik", category: "anorganik", explain: "Sangat sulit didaur ulang; sebaiknya dikurangi pemakaiannya." },
      { id: "styrofoam",    label: "Styrofoam",       category: "anorganik", explain: "Praktis tidak bisa didaur ulang; sebaiknya dihindari." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
